<section class="panel commerce-panel section"><div class="row between wrap"><h2><?= t('Shipment timeline') ?></h2><span class="pill"><?= e($shipment['carrier']) ?></span></div><p class="receipt-number"><?= e($shipment['tracking_number']) ?></p><p class="hint"><?= t('Provider state') ?>: <?= t($shipment['state']) ?></p><ol class="tracking-timeline"><?php foreach($shipment['events'] as $event): ?><li><time datetime="<?= e(date(DATE_ATOM,(int)$event['at'])) ?>"><?= dt((int)$event['at'],'Y-m-d H:i') ?></time><div><span class="eyebrow"><?= t($event['source']) ?></span><p><?= nl2br(e($event['text'])) ?></p></div></li><?php endforeach ?></ol><?php if(!$shipment['events']){empty_state('No tracking events have been published yet.','box');} ?><p class="hint"><?= t('Tracking is informational. Use the order page to confirm receipt or request after-sales service.') ?></p></section>
